/* --------------------------------------------------------------------------
   Render helpers
   -------------------------------------------------------------------------- */
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];

/** Write html into #id if that element exists. Blank content hides the section
 *  outright — an empty band of padding reads as a broken page, and several
 *  sections are legitimately empty until real content exists. */
const mount = (id, html) => {
  const n = document.getElementById(id);
  if (!n) return;
  if (!html || !String(html).trim()) { n.style.display = 'none'; return; }
  n.innerHTML = html;
};

/** Escape anything that reaches innerHTML from the URL. */
const esc = (s) => String(s).replace(/[&<>"']/g, (c) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const ticks = (items) => `<ul class="ticks">${items.map((t) => `<li>${icon('check')}<span>${t}</span></li>`).join('')}</ul>`;
const tags = (items, ghost) => `<div class="tags">${items.map((t) => `<span class="tag${ghost ? ' tag-ghost' : ''}">${t}</span>`).join('')}</div>`;
const stars = () => `<div class="stars">${icon('star').repeat(5)}</div>`;

/* Editorial index row, not a card. Ten cards read as a wall; ten rows read
   as a table of contents — and scale to twenty without redesigning. */
const serviceRow = ([slug, s], i) => `
  <a class="srv reveal" href="services/${slug}.html">
    <span class="srv-n">${String(i + 1).padStart(2, '0')}</span>
    <span class="srv-ic">${icon(s.icon)}</span>
    <span class="srv-body">
      <span class="srv-t">${s.title}</span>
      <span class="srv-d">${s.desc}</span>
    </span>
    <span class="srv-go">${icon('arrowR')}</span>
  </a>`;

const workCard = (w) => {
  const inner = `
    <div class="work-thumb"><span>${w.title.charAt(0)}</span></div>
    <div class="work-body">
      <div class="niche">${w.niche}</div>
      <h3>${w.title}</h3>
      ${tags(w.tags)}
      ${w.case ? `<span class="card-link">View case study ${icon('arrowR')}</span>` : ''}
    </div>`;
  return w.case
    ? `<a class="work reveal" href="work/${w.case}.html">${inner}</a>`
    : `<div class="work reveal">${inner}</div>`;
};

/* A testimonial without a name reads as invented — so name is required. */
const quoteCard = (t) => `
  <figure class="card quote reveal">
    ${stars()}
    <blockquote>“${t.quote}”</blockquote>
    <figcaption><b>${t.name}</b><span>${t.role}</span></figcaption>
  </figure>`;

/* --------------------------------------------------------------------------
   Shared chrome — header + footer, rendered on every page
   -------------------------------------------------------------------------- */
function renderChrome() {
  mount('header', `
    <div class="container nav">
      <a class="brand" href="index.html">In Your <span>Reach</span></a>
      <button class="nav-toggle" aria-label="Toggle menu" aria-expanded="false">
        <span></span><span></span><span></span>
      </button>
      <nav class="nav-links">
        ${DATA.nav.map((n) => `<a href="${n.href}">${n.label}</a>`).join('')}
        <a class="btn btn-primary" href="index.html#contact">${CONFIG.cta} ${icon("arrowR")}</a>
      </nav>
    </div>`);

  const social = Object.entries(CONFIG.social)
    .map(([k, url]) => `<a href="${url}" aria-label="${k}" target="_blank" rel="noopener">${icon(k)}</a>`).join('');

  mount('footer', `
    <div class="container">
      <div class="footer-grid">
        <div>
          <a class="brand" href="index.html">In Your <span>Reach</span></a>
          <p class="muted" style="margin-top:1rem;max-width:32ch;font-size:.9rem">
            ${CONFIG.tagline}. Strategy, creative, media and measurement under one roof —<br>with the reasoning shown, always.
          </p>
          <div class="socials">${social}</div>
        </div>
        <div>
          <h4>Services</h4>
          <ul>${Object.entries(DATA.services).map(([slug, s]) =>
            `<li><a href="services/${slug}.html">${s.title}</a></li>`).join('')}</ul>
        </div>
        <div>
          <h4>Company</h4>
          <ul>${DATA.nav.map((n) => `<li><a href="${n.href}">${n.label}</a></li>`).join('')}</ul>
        </div>
        <div>
          <h4>Get in touch</h4>
          <ul>
            <li><a href="tel:${CONFIG.phone.replace(/\s/g, '')}">${CONFIG.phone}</a></li>
            <li><a href="mailto:${CONFIG.email}">${CONFIG.email}</a></li>
            <li><span class="muted" style="font-size:.9rem">${CONFIG.address}</span></li>
          </ul>
        </div>
      </div>
      <div class="footer-bottom">
        <span>© <span id="year"></span> ${CONFIG.brand}. All rights reserved.</span>
        <span>Built for performance.</span>
      </div>
    </div>`);

  const y = $('#year'); if (y) y.textContent = new Date().getFullYear();
  // Static pages carry <a data-cta> — fill from CONFIG so the CTA can't drift.
  $$('[data-cta]').forEach((el) => { el.textContent = CONFIG.cta; });

  const toggle = $('.nav-toggle');
  if (toggle) {
    toggle.addEventListener('click', () => {
      const open = document.body.classList.toggle('nav-open');
      toggle.setAttribute('aria-expanded', String(open));
    });
    $$('.nav-links a').forEach((a) => a.addEventListener('click', () => document.body.classList.remove('nav-open')));
  }
}

