/* --------------------------------------------------------------------------
   Detail page — ?service=<slug> or ?case=<slug>
   ponytail: query-string routing + client-side render. Ceiling = SEO — crawlers
   see an empty shell and one URL per page type. Fine while this is a prototype.
   Upgrade path when you want /services/website-development indexed: a ~20-line
   node script that loops DATA and writes real .html files at build time.
   -------------------------------------------------------------------------- */
function detailHTML(params) {
  const serviceSlug = params.get('service');
  const caseSlug = params.get('case');
  const s = serviceSlug && DATA.services[serviceSlug];
  const c = caseSlug && DATA.cases[caseSlug];

  if (s) return { title: `${s.title} — ${CONFIG.brandShort}`, html: serviceDetail(s) };
  if (c) return { title: `${c.title} — ${CONFIG.brandShort}`, html: caseDetail(c, caseSlug) };
  return { title: `Not found — ${CONFIG.brandShort}`, html: notFound(serviceSlug || caseSlug) };
}

