/* --------------------------------------------------------------------------
   Reveal on scroll — native IntersectionObserver, no animation library
   -------------------------------------------------------------------------- */
function observeReveals() {
  const els = $$('.reveal:not(.in)');
  if (!('IntersectionObserver' in window)) { els.forEach((e) => e.classList.add('in')); return; }
  const io = new IntersectionObserver((entries) => {
    entries.forEach((e, i) => {
      if (!e.isIntersecting) return;
      setTimeout(() => e.target.classList.add('in'), i * 70);   // stagger siblings
      io.unobserve(e.target);
    });
  }, { threshold: 0.12, rootMargin: '0px 0px -60px 0px' });
  els.forEach((e) => io.observe(e));
}

/* --------------------------------------------------------------------------
   Self-check — open any page with ?selftest to assert routing + data integrity
   -------------------------------------------------------------------------- */
function selftest() {
  const fails = [];
  const ok = (cond, msg) => { if (!cond) fails.push(msg); };
  const q = (s) => new URLSearchParams(s);

  ok(detailHTML(q('service=ai-search-optimisation')).html.includes('AI Search Optimisation'), 'service route');
  const firstCase = Object.keys(DATA.cases)[0];
  if (firstCase) {
    ok(detailHTML(q(`case=${firstCase}`)).html.includes(DATA.cases[firstCase].title), 'case route');
    ok(detailHTML(q(`case=${firstCase}`)).html.includes('gate-form'), 'case study is gated');
  }
  ok(detailHTML(q('service=nope')).html.includes('Page Not Found'), 'unknown slug → not found');
  ok(detailHTML(q('')).html.includes('Page Not Found'), 'empty query → not found');
  ok(!detailHTML(q('service=<img src=x onerror=alert(1)>')).html.includes('<img'), 'slug is escaped, not injected as markup');

  Object.entries(DATA.services).forEach(([k, s]) => {
    ok(s.title && s.desc && s.long && s.features.length && s.benefits.length, `service "${k}" complete`);
    ok(P[s.icon], `service "${k}" icon "${s.icon}" exists`);
  });
  Object.entries(DATA.cases).forEach(([k, c]) => {
    ok(c.results.length === 4, `case "${k}" has 4 metrics`);
    ok(c.teaser && c.inside.length, `case "${k}" teaser complete`);
    // The gate is only real while the narrative stays out of the bundle.
    ['challenge', 'solution', 'features', 'quote', 'quoteBy'].forEach((f) =>
      ok(!(f in c), `case "${k}" does NOT leak private field "${f}"`));
  });
  // Every stack group must carry tools, and every tool a brand colour.
  DATA.stack.forEach((g) => {
    ok(g.tools.length && P[g.icon], `stack group "${g.group}" valid`);
    g.tools.forEach((t) => ok(/^#[0-9a-f]{6}$/i.test(t.c), `tool "${t.n}" has a hex colour`));
  });
  // Every official mark must be a real path, and every logo key a real tool.
  const toolNames = DATA.stack.flatMap((g) => g.tools.map((t) => t.n));
  const seenIds = new Map();
  Object.entries(LOGO).forEach(([n, l]) => {
    ok(toolNames.includes(n), `logo "${n}" maps to a listed tool`);
    ok(/^[-\d. ]+$/.test(l.vb) && l.vb.split(' ').length === 4, `logo "${n}" has a valid viewBox`);
    ok(l.s.length > 30 && l.s.includes('<'), `logo "${n}" has real SVG content`);
    ok(!/<script|onload=|onerror=/i.test(l.s), `logo "${n}" carries no script`);
    // ids must be unique across the whole map or gradients cross-wire on a page
    (l.s.match(/id="([^"]+)"/g) || []).forEach((raw) => {
      const id = raw.slice(4, -1);
      ok(!seenIds.has(id), `logo id "${id}" unique (also in ${seenIds.get(id)})`);
      seenIds.set(id, n);
    });
  });
  ok(Object.keys(DATA.services).length === 12, 'twelve services');
  DATA.work.forEach((w) => ok(!w.case || DATA.cases[w.case], `work "${w.title}" links to a real case study`));

  // Pillar tablist: ids unique, every pillar complete.
  const ids = DATA.pillars.map((s) => s.id);
  ok(new Set(ids).size === ids.length, 'pillar ids unique');
  DATA.pillars.forEach((s) =>
    ok(s.kicker && s.headline && s.body && s.services.length && s.outcomes.length && s.solves.length,
      `pillar "${s.id}" complete`));
  // Named problems must be unique across pillars — a repeated name reads as filler.
  const probs = DATA.pillars.flatMap((p) => p.solves.map((x) => x.n));
  ok(new Set(probs).size === probs.length, 'named problems unique across pillars');
  DATA.pillars.forEach((p) => p.solves.forEach((x) =>
    ok(x.n && x.t && x.n.length < 30, `problem "${x.n}" named and glossed`)));

  // Every service claims a real pillar (or null for the strategy wrapper),
  // and every pillar's named services exist in DATA.services.
  const titles = Object.values(DATA.services).map((s) => s.title);
  Object.entries(DATA.services).forEach(([k, s]) =>
    ok(s.pillar === null || ids.includes(s.pillar), `service "${k}" pillar "${s.pillar}" is real`));
  // Journey was cut as redundant with the pillars — make sure it stays gone.
  ok(!('journey' in DATA), 'journey section removed (was redundant with pillars)');
  ok(typeof wirePillars === 'undefined', 'tablist wiring removed');
  DATA.pillars.forEach((p) => p.services.forEach((name) =>
    ok(titles.includes(name), `pillar "${p.id}" lists real service "${name}"`)));
  ok(DATA.sectors.length >= 4, 'sectors listed');

  /* Honesty guards. These fail the build if fabricated proof comes back. */
  const FAKE = ['500+', '5X', '98%', '50+', 'Aurora Skincare', 'Pulse Fitness', 'Meridian Legal'];
  const blob = JSON.stringify([DATA.hero.stats, DATA.stats, DATA.work, DATA.clients, DATA.cases]);
  FAKE.forEach((f) => ok(!blob.includes(f), `inherited placeholder "${f}" is back in DATA`));
  DATA.testimonials.forEach((t, i) =>
    ok(t.name && t.role && t.quote, `testimonial ${i} needs a real name — anonymous reads as invented`));
  Object.entries(DATA.cases).forEach(([k, c]) =>
    ok(c.teaser && c.results.length, `case "${k}" incomplete`));
  // Arrow-key wrap: left from first → last, right from last → first.
  const wrap = (i, n) => (i + n) % n;
  ok(wrap(-1, 3) === 2, 'ArrowLeft from first wraps to last');
  ok(wrap(3, 3) === 0, 'ArrowRight from last wraps to first');
  ok(DATA.fit.good.length && DATA.fit.bad.length, 'fit lists populated');
  ok(CONFIG.cta && CONFIG.cta.length < 24, 'single CTA defined and short');
  [...DATA.process, ...DATA.whyUs].forEach((x) => ok(P[x.icon], `icon "${x.icon}" exists`));

  document.body.innerHTML =
    `<pre style="padding:2rem;font:14px ui-monospace,monospace;color:${fails.length ? '#ff6b6b' : 'var(--accent)'}">` +
    (fails.length ? `FAIL (${fails.length})\n\n` + fails.join('\n') : 'PASS — all checks green') + '</pre>';
}

/* -------------------------------------------------------------------------- */
document.addEventListener('DOMContentLoaded', () => {
  if (new URLSearchParams(location.search).has('selftest')) return selftest();
  renderChrome();
  renderHome();
  renderPortfolioPage();
  renderClientsPage();
  renderDetailPage();
  wireForm();
  wireForm('#gate-form', '#gate-status',
    'On its way — check your inbox in the next few minutes.');
  wireForm('#work-form', '#work-status',
    'Thanks — relevant examples will be with you within one business day.');
  observeReveals();
});

/* Node-only: lets build.cjs pre-render static pages. Inert in the browser. */
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { CONFIG, DATA, LOGO, icon, logo, ticks, tags, serviceDetail, caseDetail, contactSection };
}
